#!/usr/bin/env python3
"""
Fix Project Citadel R3D5B2A texture-cache bitmap const correctness.

Exact input:
  src/MacSrc/Shock.c
  SHA-256 da3909885cc1b19505c1ad353c7ca4c0b1fd7d43fc7306d78db2ba981c2e5136

The B2A draw stream returns const CitadelNativeWorldTriangle records, but
citadel_native_texture_get() and citadel_native_texture_upload() still took
mutable grs_bitmap pointers. The cache only reads the captured descriptor.

This patch:
- changes both helper interfaces to const grs_bitmap *;
- keeps the existing local cast only at gr_rsd8_convert(), whose legacy API
  is non-const even though this renderer uses it as a source decoder;
- changes no renderer behavior, counters, logging, routing, shaders or CMake.
"""

from __future__ import annotations

import argparse
import base64
import gzip
import hashlib
import shutil
import sys
from pathlib import Path

DEFAULT_ROOT = Path(
    "/c/Projects/Citadel_Citro3D_NATIVE_DEV/Source/shockolate"
)
RELATIVE = Path("src/MacSrc/Shock.c")
BEFORE_SHA256 = "da3909885cc1b19505c1ad353c7ca4c0b1fd7d43fc7306d78db2ba981c2e5136"
AFTER_SHA256 = "1150d3bcd37d7cd889b420f0626f4d473674533e6f5b65d163da03aa682417c4"
AFTER_SIZE = 295564
PAYLOAD = """"""


class PatchError(RuntimeError):
    pass


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", type=Path, default=DEFAULT_ROOT)
    parser.add_argument("--check-only", action="store_true")
    args = parser.parse_args()

    root = args.root.resolve()
    target = root / RELATIVE

    print("=" * 78)
    print("PROJECT CITADEL R3D5B2A CONST BITMAP FIX1")
    print("=" * 78)
    print(f"Target: {target}")

    try:
        if not target.is_file():
            raise PatchError(f"Missing source file: {target}")

        current = sha256(target)

        if current == AFTER_SHA256:
            print("PASS: const-correctness fix is already installed.")
            print("No files were changed.")
            return 0

        if current != BEFORE_SHA256:
            raise PatchError(
                "Unexpected Shock.c state; refusing to write.\n"
                f"Expected B2A: {BEFORE_SHA256}\n"
                f"Found:       {current}"
            )

        data = gzip.decompress(base64.b64decode(PAYLOAD))

        if len(data) != AFTER_SIZE:
            raise PatchError(
                f"Embedded payload size mismatch: "
                f"{len(data)} != {AFTER_SIZE}"
            )

        actual_payload_hash = hashlib.sha256(data).hexdigest()

        if actual_payload_hash != AFTER_SHA256:
            raise PatchError(
                "Embedded payload hash mismatch.\n"
                f"Expected: {AFTER_SHA256}\n"
                f"Found:    {actual_payload_hash}"
            )

        if args.check_only:
            print("PASS: exact B2A input and fix payload verified.")
            print("Check-only mode: no files were changed.")
            return 0

        backup = target.with_suffix(
            target.suffix + ".R3D5B2A_CONST_BITMAP_FIX1.bak"
        )
        shutil.copy2(target, backup)

        temporary = target.with_suffix(
            target.suffix + ".r3d5b2a_const.tmp"
        )
        temporary.write_bytes(data)
        temporary.replace(target)

        final_hash = sha256(target)

        if final_hash != AFTER_SHA256:
            shutil.copy2(backup, target)
            raise PatchError(
                "Post-write verification failed; original restored.\n"
                f"Expected: {AFTER_SHA256}\n"
                f"Found:    {final_hash}"
            )

        print("")
        print("PASS: R3D5B2A const bitmap fix installed.")
        print(f"Backup: {backup}")
        print("Texture cache getter:  const grs_bitmap *")
        print("Texture upload source: const grs_bitmap *")
        print("Renderer behavior:     UNCHANGED")
        print("Modified files:        Shock.c only")
        print(f"SHA-256: {AFTER_SHA256}")
        return 0

    except PatchError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
